function techOptionText(x){const bits=[];if(x.currentA!=null)bits.push(`${fmt(x.currentA)} A`);if(x.gases?.length)bits.push(x.gases.join("+"));else if(x.processGas)bits.push(x.processGas);if(x.feedMmMin!=null)bits.push(`${fmt(x.feedMmMin)} mm/min`);if(x.fileName)bits.push(x.fileName);return bits.join(" · ")||x.id}
