 if(tr&&!trStation)r.errors.push("Technologiereferenz verweist auf eine nicht vorhandene Bearbeitungsstation.");
 if(tr&&!p)r.warnings.push("Gespeicherte Technologiereferenz ist im aktuell geladenen Maschinenpaket nicht verfügbar.");
 if(p&&trStation){if(p.process&&p.process!==trStation.process)r.errors.push(`Technologie ${p.fileName||p.id} gehört zu ${p.process}, die referenzierte Station zu ${trStation.process}.`);if(p.manufacturer&&trStation.manufacturer&&!String(trStation.manufacturer).toLowerCase().includes(String(p.manufacturer).toLowerCase())&&!String(p.manufacturer).toLowerCase().includes(String(trStation.manufacturer).toLowerCase()))r.errors.push(`Technologie ${p.fileName||p.id} gehört zu ${p.manufacturer}, die Station zu ${trStation.manufacturer}.`)}
 if(p&&p.thicknessMm!=null&&Math.abs(Number(p.thicknessMm)-Number(state.project.material.thicknessMm))>.001)r.warnings.push(`Technologie ${p.thicknessMm} mm passt nicht zur Projektdicke ${state.project.material.thicknessMm} mm.`);
