 if(r.errors.length)h+=`<p class="report-error"><b>Fehler</b><br>${r.errors.map(escapeHtml).join("<br>")}</p>`;if(r.warnings.length)h+=`<p class="report-warn"><b>Hinweise</b><br>${r.warnings.map(escapeHtml).join("<br>")}</p>`;if(!r.errors.length&&!r.warnings.length)h+="<p>Alle aktuell prüfbaren Regeln sind erfüllt.</p>";h+='<p class="hint">Diese Prüfung ersetzt keine Maschinenfreigabe, Kollisionsprüfung oder Hersteller-Postprozessorvalidierung.</p>';body.innerHTML=h;$("reportDialog").showModal()
