 for(const c of ordered){const ep=sectionEndpoints(c),start=c.cam.startPoint||ep.start||C.contourCentroid(c),end=ep.end||start;if(prevEnd&&start)travel+=C.dist(prevEnd,start);cut+=C.contourLength(c)+Math.max(0,Number(c.cam?.leadIn?.lengthMm)||0)+Math.max(0,Number(c.cam?.leadOut?.lengthMm)||0);prevEnd=end}
